head.script:
// https://inswave01.atlassian.net/browse/WAEA-955



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setGridSize]<br/>GridView 컴포넌트의 너비(Width)와 높이(Height)를 설정합니다.",
    "validation" : [
        "width(필수) 파라미터로 GridView 컴포넌트의 너비(Width)를 픽셀(px)로 설정합니다.",
        "height(필수) 파라미터로 GridView 컴포넌트의 높이(Height)를 픽셀(px)로 설정합니다.",
        "width(필수) 파라미터를 음수 또는 NaN 으로 설정하면 메소드가 실행되지 않습니다.",
        "height(필수) 파라미터를 음수 또는 NaN 으로 설정하면 메소드가 실행되지 않습니다.",
        "파라미터 중 하나라도 유효하지 않으면 너비와 높이 모두 변경되지 않습니다.",
        "setGridSize() 실행 시 visibleRowNum 속성은 무시되고 GridView 의 높이가 변경됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 정적 select1 초기 선택값 세팅 (selectedIndex 초기 미적용 대응)
    par_width.setValue("900");
    par_height.setValue("500");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 컬럼 폭 합(1200px) > 그리드 초기 너비(400px) 로 가로 스크롤 확보 (너비 검증용)
//  - visibleRowNum="5" 로 초기 높이를 5행 기준 자동 설정 (@spec2 검증 전제)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (col1~col6, 15행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 그리드는 visibleRowNum=5 로 초기 높이가 5행 기준으로 자동 설정, 컬럼 폭 합(1200px) > 초기 너비(400px)\n[절차] par_width / par_height 선택 후 (setGridSize) 클릭\n[확인1] 정상값(900x500 / 700x450) 선택 시 그리드 offsetWidth/offsetHeight 가 설정 px 로 적용 (visibleRowNum 무시하고 높이 변경)\n[확인2] width 음수(-100) 또는 height NaN 선택 시 너비/높이 모두 불변(실행 전=실행 후)"', '', 'label1');

    // target 생성 (6컬럼 × 200px = 1200px, 초기 너비 400px, visibleRowNum=5)
    await scwin.createGridView();
}



// 그리드 데이터 (15행)
scwin.fillData = function () {
    let rows = [];
    for (var i = 1; i <= 15; i++) {
        rows.push({ col1: "A" + i, col2: "B" + i, col3: "C" + i, col4: "D" + i, col5: "E" + i, col6: "F" + i });
    }
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (가로 넘침 + visibleRowNum=5)
scwin.createGridView = async function () {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' checkAllType="false" id="" dataList="data:dlt_bind" visibleRowNum="5" visibleRowNumFix="true" style="width:400px;">';
    s += '<w2:caption style="" id="caption1" value="setGridSize 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="200" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column5" value="col5"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column6" value="col6"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="200" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col5" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col6" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// setGridSize 호출 : par_width / par_height 의 값을 그리드에 설정 후 적용값 확인
//  - 정상값 : setGridSize(W,H) -> 그리드 offsetWidth=W, offsetHeight=H (visibleRowNum 무시)
//  - width 음수 / height NaN : 파라미터 유효하지 않음 -> 너비/높이 모두 불변
scwin.btn_setGridSize_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // par_width / par_height 각 select 값 (NaN 은 문자열 'NaN')
    let wTok = par_width.getValue();
    let hTok = par_height.getValue();
    let vWidth = (wTok === "NaN") ? NaN : parseInt(wTok, 10);
    let vHeight = (hTok === "NaN") ? NaN : parseInt(hTok, 10);

    // 실행 전 그리드 크기
    let beforeEl = document.querySelector("[id$='target1']");
    let beforeW = beforeEl ? beforeEl.offsetWidth : 0;
    let beforeH = beforeEl ? beforeEl.offsetHeight : 0;

    // 메소드 실행
    target1.setGridSize(vWidth, vHeight);

    setTimeout(function () {
        let afterEl = document.querySelector("[id$='target1']");
        let afterW = afterEl ? afterEl.offsetWidth : 0;
        let afterH = afterEl ? afterEl.offsetHeight : 0;

        let valid = (vWidth >= 0) && (vHeight >= 0);
        if (valid) {
            bottom.setReturnValue("[적용] 설정값 width=" + vWidth + "px, height=" + vHeight + "px -> 그리드 offsetWidth=" + afterW + "px, offsetHeight=" + afterH + "px (visibleRowNum=5 무시하고 높이 변경)");
        } else {
            bottom.setReturnValue("[유효하지 않음 - 불변] 설정 시도 width=" + vWidth + ", height=" + vHeight + " -> 실행 전(" + beforeW + " x " + beforeH + "px) = 실행 후(" + afterW + " x " + afterH + "px)");
        }
    }, 300);
}
